// components/Logo.tsx
// The Capriowear wordmark -- "CAPRIO" plus a smaller "WEAR" mark, provided as
// an SVG (Figma node 680:394) and used at the left of the header. Replaces
// the earlier CAPRIO-only mark (Figma node 316:1331) sitewide, per owner
// request.
//
// Inlined as a component rather than served as a static /public asset: an
// <img> can never pick up currentColor, and this mark needs to, the same way
// Button's secondary variant, Chip and Eyebrow's muted tone do (see
// components/ui/styles.ts). The source file hardcoded fill="white"; that is
// replaced with currentColor here so the same mark can sit on a light surface
// later without a second asset, even though today it only ever renders on the
// header's ink background.
//
// Sizing is the caller's job via className (matches the lucide-react icon
// pattern already used elsewhere), not a prop: this is a fixed-aspect mark,
// not a component with size variants.
//
// Three geometries, one component:
// - Default (`stacked` unset): a 217.2x22.76 combined viewBox, "WEAR" set
//   beside "CAPRIO" via a horizontal `transform="translate(...)"`. Built
//   2026-09-02 as an approximation (decoded from a screenshot, not a direct
//   Figma export). Only Footer's own mobile mark (`footer.mobileBrandLogo`)
//   still uses this today -- every other real usage has since moved to
//   `stacked` (see below), so treat this as the retiring geometry, not the
//   current default in spirit.
// - `stacked`: the real Figma geometry (node 680:394), a combined viewBox
//   with "WEAR" set BELOW "CAPRIO" (not beside it) via a vertical
//   `transform="translate(...)"` -- Figma's own measured offset. Owner,
//   2026-09-06: "update the caprio logo in the nav bar, not in the footer.
//   Only for desktop" -- first wired to `Header.tsx`'s desktop (`xl:`)
//   brand mark only, via `header.brandLogoDesktop`. Extended twice since,
//   both same day: Footer's own desktop mark (`footer.desktopBrandLogo`,
//   Figma node 587:5755) and, separately, the header's own mobile/drawer
//   mark (`header.brandLogo`, all 6 real page callers) -- confirmed with
//   the owner that the mobile extension was intentional, not a stray edit,
//   when this file found all 6 pages already passing `stacked` on both
//   `logo` and `desktopLogo`. Footer's own mobile mark is the one
//   remaining default-geometry usage on the site today.
//   Re-fetched again 2026-09-06 (owner: "updated the desktop nav logo,
//   update it again", same Figma link) -- the node had been nudged smaller
//   since the first pull (`680:394`'s frame went from 141x38 to
//   ~137.29x37), so the viewBox/paths/translate below are this session's
//   fresh export, not the original pull. Same shape (WEAR below CAPRIO),
//   just Figma's current numbers -- re-check this node before assuming the
//   geometry below is still current if it's ever questioned again.
// - `footer`: Footer's own desktop mark, re-fetched as its own real node
//   for the first time (2026-09-07, owner: "updated the footer caprio
//   logo. Update it", node `587:5755` -> its `Logo` child `787:1073`).
//   Until now Footer's desktop mark reused `stacked` verbatim on the
//   (confirmed-at-the-time) assumption that the footer and header marks
//   were the same asset -- they have since diverged: `get_metadata` on
//   `787:1073` returns a genuinely different bounding box (224x57.69,
//   vs. `stacked`'s own 137.29x37 for header node `680:394`, a different
//   aspect ratio, not just a different scale), confirmed by directly
//   pulling this node rather than assuming the two still match. Same
//   shape (WEAR below CAPRIO), Figma's own current numbers for this
//   specific node -- re-check `787:1073` (not `680:394`) before assuming
//   this geometry is still current if the footer logo is ever questioned
//   again. Only Footer's desktop mark uses this; Footer's mobile mark
//   (`footer.mobileBrandLogo`) still uses `stacked`, unchanged -- this
//   request named the footer's own Figma link, not the mobile one, and no
//   Figma frame confirms mobile ever matched this node either.
// Path data for all three geometries is this file's own direct copy of
// Figma's SVG export, not hand-approximated.
import type { SVGProps } from "react";

type LogoProps = SVGProps<SVGSVGElement> & {
  /** Figma's real stacked geometry (WEAR below CAPRIO) -- see file header. */
  stacked?: boolean;
  /** Footer desktop's own mark (Figma node 787:1073, inside "Desktop
   *  Footer" 587:5755) -- see file header for why this is a third,
   *  separate geometry rather than a reuse of `stacked`. */
  footer?: boolean;
};

